# -*- coding: utf-8 -*-
"""12 Дней Снаряждества: снаряжение, броня, транспорт, киберимплант (тексты вручную по книге, цены по итоговой таблице)."""
from common import *

ARM = 'ПРАВАЯ КИБЕРРУКА (CYBERARM R)'


def build(out):
    P = 'dlc02'
    out.pack(P, '12 Дней Снаряждества', '12 Days of Gearmas')

    def lib(sub):
        e = find(P, sub, 'item')
        return {'Lib': e['id'], 'Page': e['page']}

    out.add(P, 'gear', 'Raven MicroCybernetics КиберКамера EX-1', cost=1000, Group='Техника',
            Info='Наголовная профессиональная камера. Когда Медиа публикует историю прямой трансляцией (ролевая способность, стр. 151), бонус правдоподобия растёт на 1 (например, с 2 из 10 до 3 из 10). Суммируется с бонусами от проверяемых доказательств.', **lib('КиберКамера'))
    out.add(P, 'gear', 'Киберсканер', cost=1000, Group='Техника',
            Info='Сканирует цель в пределах 2 м/ярдов и выводит данные обо всём установленном хроме. Занимает 1 минуту, цель всё время неподвижна. Если что-то из оборудования экранировано от ЭМИ, технически улучшено или уникально/неизвестно/кастомное — выводится ошибка.', **lib('КиберСканер'))
    out.add(P, 'cyber', 'Интегрированный киберсканер', cost=500, Install='Клиника', HL='7 (2d6)', Category=ARM, Slots=2,
            Info='Опция киберруки, 2 слота. Киберсканер встроен в руку; показания выводятся на LED-панель или на сопряжённый Хирон или Агент.', **lib('Интегрированный'))
    out.add(P, 'gear', 'Смарт-палочки DPI', cost=500, Group='Развлечения',
            Info='Электронные барабанные палочки: барабаньте на любой поверхности. +1 к проверке «Игра на инструменте (ударные)»; бонус применяется один раз и не суммируется с другими инструментами с таким бонусом.', **lib('Смарт-Палочки'))
    out.add(P, 'gear', 'Смарт-перчатка Xtra-Dex от Dynalar', cost=1000, Group='Техника',
            Info='2 слота опций киберруки/киберконечности; считается кистью для модульных пальцев (совместима с 5 пальцами). Киберпальцы встроены в пальцы перчатки и не добавляют пальцев кисти владельца. Опции в слотах перчатки и модульные пальцы доступны, пока перчатка подключена через Личный Порт. Надеть/снять — действие (с подключением/отключением порта). Опции в киберруке или мясной руке под перчаткой недоступны. Не скрывается.', **lib('Xtra-Dex'))
    out.add(P, 'armor', 'Костюм РХБЗ Esporma', cost=5000, SP=8, Suit=True,
            Info='Покупается комплектом и надевается сразу на голову и тело; каждая часть ОС 8, чинятся одновременно. Защищает от радиации. Баллон с кислородом на 30 минут (наполнение из окружающей среды — 1 час). Пока костюм не теряет ОС, наномашины восстанавливают 1 ОС в час.', **lib('РХБЗ'))
    out.add(P, 'gear', 'Анализатор Green Light Go от Hammered Industries', cost=100, Group='Техника',
            Info='Действием проверяет дозу препарата или уличного наркотика: зелёный индикатор — чистое вещество по внутренней базе, красный — загрязнено. Что именно за вещество — не сообщает.', **lib('Green Light'))
    out.add(P, 'gear', 'Ионные наручники', cost=500, Group='Спецсредства',
            Info='Любое не экранированное от ЭМИ оборудование в не экранированной киберконечности, скованной наручниками, недоступно, пока их не снимут. Ломаются, если у ломающего ТЕЛ 13 и выше.', **lib('Ионные'))
    out.add(P, 'gear', 'Набор инструментов «Мастер-механик»', cost=20000, Group='Инструменты',
            Info='Даёт технику +4 к проверкам Базовой техники, Кибертехники, Автомеханики, Морской техники, Авиатехники, Электроники/Безопасности и Оружейника, когда они используются для ролевой способности (стр. 147). Считается толстым металлическим укрытием; без спецоборудования или персонажа с ТЕЛ 10+ не перемещается.', **lib('Мастер-Механик'))
    out.add(P, 'gear', 'Колонки MiniMag от Telectronics', cost=50, Group='Развлечения',
            Info='Магнитные динамики диаметром 2,4 см; по беспроводной сети подключаются к связанному Агенту в радиусе 100 м/ярдов. Разные цвета.', **lib('MiniMag'))
    out.add(P, 'gear', 'Дальномер MagViewer от Optitech', cost=500, Group='Оптика',
            Info='Бинокль: детальный обзор до 800 м/ярдов. Успешная вспомогательная проверка навыка с дальномером при одиночном/прицельном выстреле по цели на 51 м/ярд и дальше даёт +1 к атаке (сверх обычного бонуса вспомогательной проверки). Не суммируется со снайперским прицелом и опцией киберглаза ТелеОптика.', **lib('MagViewer'))
    out.add(P, 'armor', 'КомпактЩит от SkidRow', cost=100, SP=10, Shield=True,
            Info='Стильный рюкзак (Businesswear): нажмите кнопку — панели раскрываются в баллистический щит (ОС10). В виде рюкзака защиты не даёт и считается обычной сумкой; для эффективного использования щит нужно держать в руке. Нельзя поставить в опцию киберруки «Выкидной щит».', **lib('КомпактЩит'))
    out.add(P, 'vehicle', 'Zonda Metrocar', cost=1000,
            Info='Доступный городской двухместный автомобиль (бывший веломобиль Yang\'s Wheels по лицензии Zonda). Несовместим с «Усиленным шасси» и «Улучшением сидений». Техник не может улучшить его скорость — ни боевую, ни повествовательную.',
            Extra={'nomad': '1', 'hp': '25', 'seats': '2', 'combat': '10', 'narrative': '30 миль/ч / 48 км/ч'}, **lib('Zonda'))
